/**
 * @fileoverview Utility functions for debouncing and throttling function calls.
 */

/**
 * Creates a debounced function that delays invoking the given function until
 * after `wait` milliseconds have elapsed since the last time the debounced
 * function was called.
 *
 * @param {Function} func - The function to debounce.
 * @param {number} wait - The number of milliseconds to delay.
 * @param {Object} [options] - Optional settings.
 * @param {boolean} [options.leading=false] - Whether to invoke the function on
 *   the leading edge of the timeout.
 * @param {boolean} [options.trailing=true] - Whether to invoke the function on
 *   the trailing edge of the timeout.
 * @returns {Function} The new debounced function.
 */
export function debounce(func, wait, options = {}) {
  let lastCallTime = 0;
  let timer = null;
  let lastArgs = null;
  let lastThis = null;
